using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;
public static class NurseDetailRender {
 const string Out=RebirthEntityStudio.RebirthNurseDetailFit.Output;
 public static void Run(){NurseAnatomyRender.RenderOnly();foreach(string n in new[]{"FrontRest","FrontAPose","SideAPose"})File.Copy(RebirthEntityStudio.RebirthNurseAnatomyFit.Output+"/Nurse_Moe_"+n+".png",Out+"/Nurse_Moe_"+n+".png",true);Hands("Left");Hands("Right");Face("Face_After");Face("Face_NoNormal");Face("Face_NoPacked");Hair(0);Hair(4);}
 public static void FaceBefore(){Face("Face_Before");}
 static GameObject[] Models(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var nurse=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(RebirthEntityStudio.RebirthNurseNativeAssembly.Folder+"/RebirthNurse_Authoring.prefab"));var moe=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/NativeReferences/Moe/PrefabInstance/ZMoe.prefab"));nurse.GetComponent<Animator>().enabled=false;moe.GetComponent<Animator>().enabled=false;RebirthEntityStudio.RebirthNurseNativeShaderPreview.Bind(nurse);foreach(var r in moe.GetComponentsInChildren<SkinnedMeshRenderer>(true))r.sharedMaterials=r.sharedMaterials.Select(m=>{var material=new Material(m);material.shader=RebirthEntityStudio.RebirthNativeShaderLibrary.Get(m.name=="HD_Moe"?"Game/Character":"Game/Autodesk");return material;}).ToArray();foreach(var m in new[]{nurse,moe})m.GetComponent<LODGroup>().ForceLOD(0);return new[]{nurse,moe};}
 static void Skin(GameObject[] models,string handSide=null){foreach(var model in models)foreach(var r in model.GetComponentsInChildren<SkinnedMeshRenderer>(true))if(r.enabled&&r.gameObject.activeInHierarchy&&(!r.name.StartsWith("LOD")||r.name=="LOD0")){var g=new GameObject("__CPU");var preview=NurseAnatomyRender.WorldSkin(r);if(handSide!=null){var bw=r.sharedMesh.boneWeights;var keep=bw.Select(w=>new[]{new{index=w.boneIndex0,weight=w.weight0},new{index=w.boneIndex1,weight=w.weight1},new{index=w.boneIndex2,weight=w.weight2},new{index=w.boneIndex3,weight=w.weight3}}.Any(x=>x.weight>.15f&&r.bones[x.index]!=null&&r.bones[x.index].name.StartsWith(handSide+"Hand"))).ToArray();for(int sub=0;sub<preview.subMeshCount;sub++){var input=preview.GetTriangles(sub);var indices=new System.Collections.Generic.List<int>();for(int k=0;k<input.Length;k+=3)if(keep[input[k]]||keep[input[k+1]]||keep[input[k+2]]){indices.Add(input[k]);indices.Add(input[k+1]);indices.Add(input[k+2]);}preview.SetTriangles(indices,sub);}preview.RecalculateBounds();}g.AddComponent<MeshFilter>().sharedMesh=preview;g.AddComponent<MeshRenderer>().sharedMaterials=r.sharedMaterials;r.forceRenderingOff=true;}}
 static Camera Camera(Vector3 centre,float size,int width,int height,Vector3 direction){var c=new GameObject("Camera").AddComponent<Camera>();c.orthographic=true;c.orthographicSize=size;c.aspect=(float)width/height;c.transform.position=centre+direction;c.transform.LookAt(centre);c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.13f,.16f,.19f);c.nearClipPlane=.01f;var key=new GameObject("Key").AddComponent<Light>();key.type=LightType.Directional;key.intensity=1.1f;key.transform.rotation=Quaternion.Euler(35,145,0);RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.48f,.48f,.48f);var fill=new GameObject("Fill").AddComponent<Light>();fill.type=LightType.Directional;fill.intensity=.65f;fill.transform.rotation=Quaternion.Euler(15,-35,0);return c;}
 static void Save(Camera camera,string name,int width,int height){var rt=new RenderTexture(width,height,24);camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var texture=new Texture2D(width,height,TextureFormat.RGB24,false);texture.ReadPixels(new Rect(0,0,width,height),0,0);texture.Apply();File.WriteAllBytes(Out+"/"+name+".png",texture.EncodeToPNG());RenderTexture.active=null;camera.targetTexture=null;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(texture);}
 static void Hands(string side){var models=Models();foreach(var model in models){var b=model.GetComponentsInChildren<Transform>(true).ToDictionary(t=>t.name);var finger=(b[side+"HandMiddle4"].position-b[side+"HandMiddle1"].position).normalized;var spread=b[side+"HandIndex1"].position-b[side+"HandPinky1"].position;var normal=Vector3.Cross(finger,spread).normalized;var orientation=Quaternion.LookRotation(-normal,-finger);var q=Quaternion.LookRotation(Vector3.back,Vector3.up)*Quaternion.Inverse(orientation);var centre=(b[side+"Hand"].position+b[side+"HandMiddle4"].position)*.5f;model.transform.rotation=q;model.transform.position=new Vector3(model==models[0]?-.19f:.19f,0,0)-q*centre;}Skin(models,side);var camera=Camera(Vector3.zero,.19f,1600,800,Vector3.forward);var mat=new Material(Shader.Find("Hidden/Internal-Colored"));mat.SetInt("_ZTest",(int)CompareFunction.Always);mat.SetInt("_ZWrite",0);mat.SetInt("_Cull",0);Camera.CameraCallback callback=c=>{if(c!=camera)return;mat.SetPass(0);GL.PushMatrix();GL.LoadPixelMatrix(0,1600,0,800);GL.Begin(GL.QUADS);foreach(var model in models){GL.Color(model==models[0]?Color.cyan:new Color(.5f,1,.2f));var hand=model.GetComponentsInChildren<Transform>(true).Single(t=>t.name==side+"Hand");foreach(var bone in hand.GetComponentsInChildren<Transform>(true))if(bone!=hand)NurseAnatomyRender.Line(camera,bone.position,bone.parent.position);}GL.End();GL.PopMatrix();};UnityEngine.Camera.onPostRender+=callback;Save(camera,side+"Hand_Comparison",1600,800);UnityEngine.Camera.onPostRender-=callback;}
 static void Face(string label){var models=Models();models[0].transform.position=Vector3.left*.23f;models[1].transform.position=Vector3.right*.23f;var material=models[0].GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="LOD0").sharedMaterial;if(label=="Face_NoNormal")material.SetTexture("_Normal",null);if(label=="Face_NoPacked"){var texture=new Texture2D(2,2,TextureFormat.RGBA32,false,true);texture.SetPixels(Enumerable.Repeat(new Color(.75f,0,1,0),4).ToArray());texture.Apply();material.SetTexture("_RMOE",texture);}Skin(models);var c=Camera(new Vector3(0,1.64f,.02f),.23f,1600,800,Vector3.forward);Save(c,label,1600,800);}
 static void Hair(int degrees){var models=Models();UnityEngine.Object.DestroyImmediate(models[1]);var model=models[0];foreach(var bone in model.GetComponentsInChildren<Transform>(true).Where(t=>t.name.StartsWith("Hair_")))bone.localRotation*=Quaternion.Euler(0,degrees*.25f,degrees*.22f);Skin(new[]{model});var c=Camera(new Vector3(0,1.53f,-.04f),.29f,1000,1000,new Vector3(.7f,0,-.8f));Save(c,"Hair_WeightPreview_"+degrees,1000,1000);}
}



